<script setup lang="ts">const route=useRoute(),config=useRuntimeConfig(),{api,media,token}=useShopApi();const{data:a}=await useAsyncData(`article-${route.params.slug}`,()=>api<any>(`/articles/${route.params.slug}`));const description=computed(()=>a.value?.seo?.description||a.value?.excerpt||a.value?.title);useSeoMeta(()=>({title:a.value?.seo?.title||a.value?.title||'مقاله',description:description.value,ogTitle:a.value?.title,ogDescription:description.value,ogImage:a.value?.cover?media(a.value.cover):undefined,ogType:'article'}));useHead(()=>({link:[{rel:'canonical',href:`${String(config.public.siteUrl).replace(/\/$/,'')}/blog/${route.params.slug}`}]}));const saved=ref(false),body=ref(''),message=ref('');async function save(){if(!token.value)return navigateTo('/login');const r=await api<any>(`/saved-articles/${a.value.id}`,{method:'POST'});saved.value=r.is_saved}async function comment(){if(!token.value)return navigateTo('/login');const r=await api<any>(`/comments/article/${a.value.id}`,{method:'POST',body:{body:body.value}});message.value=r.message;body.value=''}</script>
<template><article v-if="a" class="mx-auto max-w-4xl px-4 py-10"><p class="text-sm text-slate-400">مجله / {{a.title}}</p><h1 class="mt-5 text-3xl font-black leading-tight md:text-5xl">{{a.title}}</h1><div class="mt-5 flex items-center justify-between text-sm text-slate-400"><span>{{new Date(a.published_at).toLocaleDateString('fa-IR')}}</span><button class="rounded-xl border px-4 py-2 font-bold" @click="save">{{saved?'ذخیره شد ✓':'ذخیره مقاله'}}</button></div><img v-if="a.cover" :src="media(a.cover)" class="mt-8 aspect-video w-full rounded-3xl object-cover"><div class="mt-10 whitespace-pre-line text-base leading-9 text-slate-700">{{a.body}}</div><section class="mt-14 border-t pt-8"><h2 class="text-xl font-black">دیدگاه‌ها</h2><form class="mt-5" @submit.prevent="comment"><textarea v-model="body" required rows="4" class="w-full rounded-2xl border p-4" placeholder="نظر شما درباره این مطلب…"/><p v-if="message" class="mt-2 text-sm text-emerald-700">{{message}}</p><button class="mt-3 rounded-xl bg-brand-700 px-6 py-3 font-bold text-white">ارسال دیدگاه</button></form><div class="mt-7 space-y-3"><div v-for="c in a.comments" :key="c.id" class="rounded-2xl bg-white p-5"><p class="font-bold">{{c.user?.name||'کاربر'}}</p><p class="mt-2 text-sm leading-7 text-slate-600">{{c.body}}</p></div></div></section></article></template>
